import { queryInfo } from "../lib/a2s";
import { agentNeighbors } from "../lib/node-agent";
import { nodeIpInventory, localNeighbors } from "../lib/node-ip-inventory";
import {
  GUEST_IDENTITY_CMD,
  parseGuestIdentity,
  guestIdentityVerdict,
  smbiosUuid,
  ipConflictReason,
  startupProbeCommand,
  parseStartupProbe,
  lastErrorLines,
  redactSecrets,
  secretValuesFromConfig,
} from "../lib/provision-guard";
import { checkGamePortOpen, gameFamilyForServer, gamePortBoundInGuest } from "../worker/provision-health";
import { dockerContainerNameFrom } from "../worker/game-variant";
import { serverRootPassword } from "../lib/sftp";
import { healthSupported, judgeModHealth } from "../lib/mod-health";

type Verdict = "PASS" | "WARN" | "FAIL";
type Check = { name: string; verdict: Verdict; detail: string };

export function overall(checks: readonly Check[]): { clean: boolean; failed: string[]; warned: string[] } {
  return {
    clean: checks.every((c) => c.verdict === "PASS"),
    failed: checks.filter((c) => c.verdict === "FAIL").map((c) => c.name),
    warned: checks.filter((c) => c.verdict === "WARN").map((c) => c.name),
  };
}
