/**
 * Schema field key -> itzg/docker-minecraft-bedrock-server env var name +
 * value formatting. Same rationale as PALWORLD_ENV_MAP above: this image
 * regenerates its config from these env vars on every boot, so the ONLY way
 * to change a setting for real is to recreate the container with a new
 * environment — never editing a config file in place, which the next boot
 * would just overwrite anyway.
 *
 * Verified against the image's own documented env vars (its README), not
 * guessed from the field's schema key — see BEDROCK's own schema comment in
 * lib/game-config.ts for why a generic 1:1 rename would be wrong here
 * (`max-players` -> `MAX_PLAYERS`, `white-list` -> `ALLOW_LIST`, etc., not a
 * literal case-fold of the field key).
 */
const BEDROCK_ENV_MAP: Record<string, { env: string; format: (v: string | number | boolean) => string }> = {
  VERSION: { env: "VERSION", format: (v) => String(v) },
  gamemode: { env: "GAMEMODE", format: (v) => String(v) },
  difficulty: { env: "DIFFICULTY", format: (v) => String(v) },
  "max-players": { env: "MAX_PLAYERS", format: (v) => String(v) },
  "allow-cheats": { env: "ALLOW_CHEATS", format: (v) => bool(v) },
  "level-name": { env: "LEVEL_NAME", format: (v) => String(v) },
  "level-seed": { env: "LEVEL_SEED", format: (v) => String(v) },
  "online-mode": { env: "ONLINE_MODE", format: (v) => bool(v) },
  "view-distance": { env: "VIEW_DISTANCE", format: (v) => String(v) },
  "white-list": { env: "ALLOW_LIST", format: (v) => bool(v) },
};

async function applyBedrock(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  const envMap = await readContainerEnv(conn, BEDROCK_CONTAINER);
  if (!envMap) {
    return { ok: false, applied: [], notes: [`Could not find the "${BEDROCK_CONTAINER}" container — nothing was changed.`] };
  }

  const applied: string[] = [];
  for (const [key, val] of Object.entries(v)) {
    const mapping = BEDROCK_ENV_MAP[key];
    if (!mapping || val == null) continue;
    // A blank level-seed means "let the server pick one" (the schema's own
    // default) — setting LEVEL_SEED="" is not the same as leaving it unset
    // for every image, so skip it entirely rather than risk forcing an
    // empty-string seed the image might treat literally.
    if (key === "level-seed" && String(val).trim().length === 0) continue;
    envMap.set(mapping.env, mapping.format(val));
    applied.push(key);
  }
  if (applied.length === 0) {
    return { ok: true, applied: [], notes: ["No changes to apply."] };
  }

  await writeEnvFile(conn, sftp, "/root/bedrock.env", envMap);

  // Port + volume exactly as prisma/catalog.ts provisions them (EULA is
  // customer-invisible — always true, matches what checkout already implies).
  const res = await recreateGameContainer(conn, {
    family: "bedrock",
    container: BEDROCK_CONTAINER,
    runFlags: "-p 19132:19132/udp -v /opt/bedrock:/data --env-file /root/bedrock.env",
    image: "itzg/minecraft-bedrock-server",
  });
  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };

  return {
    ok: true,
    applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`],
    notes: ["Your server restarted briefly to apply these — any connected players were disconnected and can rejoin now."],
  };
}

