/**
 * Rust: the `oxide` server type turns on the Oxide framework that
 * didstopia/rust-server ships (RUST_OXIDE_ENABLED=1; it downloads Oxide on
 * boot and keeps it current with RUST_OXIDE_UPDATE_ON_BOOT=1). Before
 * 2026-10-02 the type was only a label: nothing in the platform ever set the
 * variable (docs/MODS-COVERAGE.md), so the Mods tab refused every plugin.
 * `carbon` is deliberately not mapped: the image has no Carbon switch.
 * Unverified on a live server (no real provision possible from the build
 * session) — see docs/DOCUMENTATION.md, "Growth batch G5".
 */
export const RUST_OXIDE_ENV = { RUST_OXIDE_ENABLED: "1", RUST_OXIDE_UPDATE_ON_BOOT: "1" } as const;

export function applyGameVariant(setupScript: string, family: string | null, variant: string | null): string {
  if (family === "rust") {
    if (variant !== "oxide") return setupScript;
    if (/-e\s+RUST_OXIDE_ENABLED=/.test(setupScript)) return setupScript;
    const flags = Object.entries(RUST_OXIDE_ENV).map(([k, v]) => `-e ${k}=${v}`).join(" ");
    return setupScript.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 ${flags}`);
  }
  if (family !== "minecraft") return setupScript;
  if (!variant) return setupScript;
  if (/-e\s+TYPE=/.test(setupScript)) return setupScript;
  const type = variant.toUpperCase();
  return setupScript.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e TYPE=${type}`);
}

/**
 * Substitute the Minecraft image's Java-runtime tag to match the customer's
 * checkout-time VERSION choice.
 *
 * FOUND LIVE 2026-09-20: unlike every other customizable field, the
 * `itzg/minecraft-server` IMAGE TAG in `prisma/catalog.ts`'s setupScript is
 * not a `-e KEY=...` docker env var — it's the image reference itself — so
 * `applyGameConfigEnv` below (which only ever rewrites `-e KEY=` placeholders)
 * never touched it. Every Minecraft server was provisioned on the catalog's
 * static `:java21` regardless of the VERSION actually picked at checkout,
 * silently crash-looping any version needing a different Java (26.1+ needs
 * Java 25 — see lib/game-config.ts's MINECRAFT_JAVA_CUTOVERS for the real,
 * researched mapping and the live incident that found this).
 *
 * Deliberately minecraft-only and deliberately narrow: touches ONLY the
 * `itzg/minecraft-server(:tag)?` image reference, nothing else in the script.
 * Falls back to the schema's own VERSION default when the customer's
 * `gameConfig` doesn't carry one (an order that never touched the field) —
 * matching today's catalog default (1.21.1 -> java21) exactly, so a customer
 * who never touches VERSION sees no change in behavior.
 */
export function applyMinecraftJavaImage(
  setupScript: string,
  family: string | null,
  gameConfig: Record<string, unknown> | null | undefined
): string {
  if (family !== "minecraft") return setupScript;
  if (!/itzg\/minecraft-server(:[\w.-]+)?/.test(setupScript)) return setupScript;
  const version = gameConfig && gameConfig["VERSION"] != null ? String(gameConfig["VERSION"]) : "1.21.1";
  const image = minecraftImageForVersion(version);
  return setupScript.replace(/itzg\/minecraft-server(:[\w.-]+)?/, image);
}

/**
 * The generalization this file's own docstring called for: substitute a
 * customer's checkout-time `Server.gameConfig` values into an OsTemplate's
 * setupScript, for whichever fields already appear in it as a docker
 * `-e KEY=...` env-var placeholder.
 *
 * Found live 2026-08-31 auditing DST (`dst` family): the whole per-family
 * customization schema in lib/game-config.ts (`ConfigField`, one per
 * `docker run -e KEY=...` in prisma/seed-wave4-games.ts and its Wave 1-3
 * predecessors) is captured at checkout into `Server.gameConfig`
 * (lib/game-order.ts) and shown in the post-deploy Settings tab, but — same
 * root cause as `applyGameVariant` above, just never generalized —
 * `provision()` in worker/index.ts never read it. Every family's setup
 * script always ran with its hardcoded static default (usually `''`),
 * regardless of what the customer entered at checkout. For most fields that
 * meant a cosmetically-wrong default (wrong MOTD, wrong hostname string);
 * for DST's `TOKEN` (an online DST cluster refuses to start with none — see
 * lib/game-config.ts's DST schema comment) it meant the container never
 * bound its port at all and PROVISION's own `checkGamePortOpen` health check
 * would time out and hard-fail the customer's paid order.
 *
 * Deliberately conservative: ONLY touches a key if the setupScript already
 * declares it as `-e KEY=...` — fields with no such placeholder (e.g. DST's
 * `PASSWORD`, which the yeetzone image never wired to an env var at all) are
 * left untouched rather than guessing a docker flag that isn't there.
 * Values are re-quoted as a single-quoted shell literal with proper `'`
 * escaping (`'\''`) so a customer-supplied string can never break out of the
 * quote and inject shell — the same safety property `validateConfig`'s own
 * control-character guard exists for, just extended to this second consumer

 * applied gets a real chance to take effect), and minting BRAND NEW
 * per-server secrets for palworld/rust/cs2 on every call — the same
 * "reinstall rotates credentials, never keeps the old ones" rule
 * `reinstall()`'s own comment (worker/index.ts) applies to the VPS root
 * password.
 */
/**
 * left4devops/l4d2: seed the bind-mounted /cfg from the image before the game starts.
 *
 * ROOT CAUSE of "the L4D2 server never becomes connectable" (reproduced 2026-10-04,
 * docs/DOCUMENTATION.md "L4D2 never connectable"): the image's `/cfg` is NOT empty - it
 * holds the 46 files the dedicated server execs at boot (valve.rc, config_default.cfg,
 * the cpu_/gpu_/mem_level_*.ekv tables, ...) and `left4dead2/cfg` is a symlink to it.
 * `-v /opt/l4d2/cfg:/cfg` is a BIND mount, and unlike a named volume docker does not copy
 * the image's content into a bind mount, so the empty host directory hid every one of
 * them. srcds_linux then starts, prints "Server is hibernating", never loads the +map,
 * stays at ~70 MB RSS and answers no A2S query - while its TCP RCON listener still
 * accepts connections, which is exactly what our TCP health check looked at.
 *
 * The fix copies the image's own /cfg into the host directory (no-clobber, so a
 * customer's edits survive a re-run) as the container's uid 1000, then the real
 * container starts. Idempotent; a script that already carries the seed is left alone.
 * Also makes DEFAULT_MAP / GAME_TYPES real docker env (the schema fields existed but
 * applyGameConfigEnv only rewrites an env var that is already present in the script).
 */
export function applyL4d2CfgSeed(setupScript: string, family: string | null): string {
  if (family !== "l4d2" || !/left4devops\/l4d2/.test(setupScript)) return setupScript;
  let out = setupScript;
  if (!out.includes("--entrypoint /bin/cp")) {
    const seed =
      "docker run --rm --user 1000:1000 -v /opt/l4d2/cfg:/seed --entrypoint /bin/cp left4devops/l4d2:latest -an /cfg/. /seed/ && ";
    out = out.replace(/docker run\s+(?:-d|--detach)\b/, `${seed}$&`);
  }
  if (!/-e\s+DEFAULT_MAP=/.test(out)) out = out.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e DEFAULT_MAP='c1m1_hotel'`);
  if (!/-e\s+GAME_TYPES=/.test(out)) out = out.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e GAME_TYPES=''`);
  return out;
}

export function buildGameSetupScript(server: {
  /** Needed by fivem (per-server derived secrets); every real caller passes the Server row. */
  id?: string;
  osTemplate: { setupScript: string | null; family: string | null };
  gameVariant?: string | null;
  gameConfig?: unknown;
  /** Minecraft only: an exact mirrored jar to stage + pin (worker/mcjar-pin.ts#mcJarPinForSetup), or null for upstream behaviour. */
  __mcJarPin?: PinPlan | null;
  /** Terraria only: image tag + optional mirror tarball for the fresh install (worker/terraria-target.ts#terrariaSetupPlan). */
  __terrariaPlan?: { version: string; mirror: { url: string; sha256: string } | null } | null;
  // The VM's real RAM (GamePlan.ramMB, else the VPS plan's). Optional: a
  // caller that doesn't load the plan (GAME_REINSTALL today) keeps the
  // catalog's heap exactly as before.
  // Index signature: callers pass their own partial selects (GAME_REINSTALL's
  // gamePlan is `{ gameFamily }`), which TS's weak-type check would reject.
  gamePlan?: { ramMB?: number | null; [k: string]: unknown } | null;
  plan?: { ramMB?: number | null; [k: string]: unknown } | null;
}): string | null {
  if (!server.osTemplate.setupScript) return null;
  const scriptWithDocker = applyL4d2CfgSeed(skipDockerInstallIfPresent(server.osTemplate.setupScript), server.osTemplate.family);
  const scriptWithVariant = applyGameVariant(scriptWithDocker, server.osTemplate.family, server.gameVariant ?? null);
  const scriptWithEnv = applyGameConfigEnv(
    scriptWithVariant,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
  );
  // Terraria (2026-10-02): its settings are launch args + a TShock config.json, not `-e` env, so
  // applyGameConfigEnv cannot express them — bake them in so a fresh install / reinstall starts configured.
  const scriptWithTerrariaConfig = (() => {
    if (server.osTemplate.family !== "terraria" || !server.gameConfig) return scriptWithEnv;
    const v = validateConfig("terraria", server.gameConfig as Record<string, unknown>);
    return v.ok ? applyTerrariaSetup(scriptWithEnv, v.values) : scriptWithEnv;
  })();
  // Family setup pipeline (integration, 2026-10-02): every family applier that has to bake settings into the
  // setup script (because they are launch args / seeded files / composed env, not plain `-e` placeholders) is a
  // pure rewrite applied here, each EXACTLY ONCE, in this order. Each step is a no-op for other families.
  const scriptWithFamilySetup = (() => {
    const fam = server.osTemplate.family;
    let script = scriptWithTerrariaConfig;
    // survival families (vrising/enshrouded/icarus/sunkenland/nightingale): missing env baked in. Runs for every
    // family (it no-ops for others) and with a null gameConfig exactly as it did before the merge.
    script = applySurvivalSetup(script, server.osTemplate.family, server.gameConfig);
    // ark/arkasa/conan/soulmask/theisle/dragonwilds (cfg-unreal): env with no catalog placeholder, composed flags,
    // the map/mode variant and The Isle's Game.ini. Like the survival step it runs unconditionally (no-op for other families).
    script = applyUnrealSetupFor(script, server.osTemplate.family, server.gameConfig, server.gameVariant ?? null);
    // factorio/satisfactory/corekeeper/necesse/barotrauma (cfg-coop): fresh-install bake, lib/game-applier-specs/coop-setup.ts.
    script = applyCoopFamilySetup(script, server.osTemplate.family, server.gameConfig);
    // projectzomboid/dst/unturned/theforest/sonsoftheforest (cfg-mixed): fresh-install bake.
    script = applyMixedFamilySetup(script, server.osTemplate.family, server.gameConfig);
    if (!fam || !server.gameConfig) return script;
    // Source-engine families (cs2/cs16/tf2/l4d2/gmod/kf2): bake the saved settings that the generic env substitution
    // cannot express (undeclared env vars, 0/1 translation, gmod GAME_PARAMS, cfg seeds).
    if (["cs2", "cs16", "tf2", "l4d2", "gmod", "kf2"].includes(fam)) {
      const v = validateConfig(fam, server.gameConfig as Record<string, unknown>);
      if (v.ok) script = applySourceSetup(script, fam, v.values);
    }
    // sandstorm: map/password/max players are ONE composed LAUNCH_SERVER_ENV — bake it so a fresh install / reinstall starts configured.
    if (fam === "sandstorm") {
      const v = validateConfig("sandstorm", server.gameConfig as Record<string, unknown>);
      if (v.ok) script = applySandstormSetup(script, v.values);
    }
    // Mordhau + Squad ("sim" appliers): Mordhau's ini files are seeded before first boot, Squad's MODS env is added
    // (its SERVER_NAME/FIXEDMAXPLAYERS are already `-e` placeholders).
    if (fam === "mordhau" || fam === "squad") {
      const v = validateConfig(fam, server.gameConfig as Record<string, unknown>);
      if (v.ok) script = fam === "mordhau" ? applyMordhauSetup(script, v.values) : applySquadSetup(script, v.values);
    }
    return script;
  })();
  // Terraria image: pin the tag and stage the tarball from our mirror when we have it (registry pull is the fallback).
  const scriptWithConfig = server.osTemplate.family === "terraria" ? applyTerrariaImage(scriptWithFamilySetup, server.__terrariaPlan) : scriptWithFamilySetup;
  // Minecraft server-software mirror (lib/mcjars/pin.ts): stage the exact jar on
  // the guest and run it pinned, so container restarts never contact upstream
  // (2026-10-01 PaperMC outage). A pinned LATEST resolves to the concrete
