    conn,
    `docker rm -f ${container}-old 2>/dev/null; ${stopCmd} && docker rename ${container} ${container}-old`
  );
  if (prep.code !== 0) {
    return { ok: false, note: `Could not stop the running server to apply changes: ${prep.stderr || prep.stdout}` };
  }

