  // re-adding docker's policy is precisely what wrapDockerGameService strips.
  const createCmd = unit
    ? `docker create --name ${container} ${runFlags} ${image}`
    : `docker run -d --name ${container} ${runFlags} --restart unless-stopped ${image}`;
  const startCmd = unit ? ` && systemctl start '${shq(unit)}'` : "";
  const rollback =
    `docker rm -f ${container} 2>/dev/null; docker rename ${container}-old ${container} && ` +
    (unit ? `systemctl start '${shq(unit)}'` : `docker start ${container}`);

  const run = await execRemote(conn, `${createCmd} >/dev/null${startCmd}`);
  if (run.code !== 0) {
    await execRemote(conn, rollback);
    return { ok: false, note: `Failed to apply — rolled back to the previous working configuration: ${run.stderr || run.stdout}` };
