/**
 * Minecraft Bedrock: the ONE place that decides which Bedrock Dedicated Server build "Latest" means
 * and which network transport we run. Pure (no I/O) so it is unit tested.
 *
 * INCIDENT 2026-10-06 (docs/DOCUMENTATION.md, "Bedrock never opens its game port"): every fresh Bedrock
 * deploy failed with "game port 19132/udp never opened". Root cause: since BDS 1.26.50 Mojang's default
 * `transport` is `nethernet` (a WebRTC transport: ONE dual-stack TCP signalling socket on server-port, UDP
 * only negotiated per client) instead of `raknet` (UDP 19132 / 19133). A server.properties generated by
 * BDS >= 1.26.50 therefore listens on 19132/TCP and binds NO game UDP port at all, while still logging
 * "Server started." — and the image never printed the "IPv4 supported, port: 19132" line. Our container
 * publishes 19132/udp only, so nothing could ever connect (and the provision health check rightly failed).
 * Servers whose server.properties was written by an older BDS keep `transport=raknet` in the file and
 * kept working, which is why the two live customers were unaffected.
 *
 * Mojang has announced NetherNet becomes the ONLY transport from BDS 1.26.60 (RakNet removed). So:
 *   1. every Bedrock container we create sets `TRANSPORT=raknet` explicitly (itzg maps TRANSPORT onto
 *      server.properties; verified on 1.26.45.1, 50.5, 51.1, 52.3), and
 *   2. "LATEST" resolves to BEDROCK_KNOWN_GOOD_VERSION, a build WE verified, instead of whatever Mojang
 *      published last — so a future 1.26.60 can never silently break a restart/deploy.
 *
 * HOW TO BUMP BEDROCK_KNOWN_GOOD_VERSION: run a throwaway Bedrock server with the new build and the exact
 * flags below; confirm the log has "IPv4 supported, port: 19132", /proc/net/udp inside the container lists
 * 0x4ABC (19132), a RakNet unconnected ping to the published UDP port answers 0x1c, and
 * `npx tsx scripts/verify-game-provision.ts <hostname>` reports ports-guest PASS. Only then change the constant.
 * Versions with no RakNet (1.26.60+) must NOT be bumped to until NetherNet (TCP signalling) is supported.
 */

export const BEDROCK_KNOWN_GOOD_VERSION = "1.26.52.3";
/** Verified 2026-10-06 on 1.26.45.1 / 1.26.50.5 / 1.26.51.1 / 1.26.52.3. */
export const BEDROCK_TRANSPORT = "raknet";

/** Value stored for "Latest" in a server's gameConfig (kept for existing rows). */
export const BEDROCK_LATEST = "LATEST";

/** What a stored VERSION really runs. LATEST/blank -> the pinned build; PREVIEW and explicit builds pass through. */
export function resolveBedrockVersion(v: unknown): string {
  const s = v == null ? "" : String(v).trim();
  if (!s || s.toUpperCase() === BEDROCK_LATEST) return BEDROCK_KNOWN_GOOD_VERSION;
  if (s.toUpperCase() === "PREVIEW") return "PREVIEW";
  return s;
}

/** Label for the "Latest" option / variant: says honestly what it means. */
export const BEDROCK_LATEST_LABEL = `Recommended (Nxeon-tested build ${BEDROCK_KNOWN_GOOD_VERSION})`;
export const BEDROCK_PREVIEW_LABEL =
  "Preview (Microsoft's Bedrock Preview build; untested by Nxeon and may not accept connections)";

const VERSION_ENV_RE = /(-e\s+VERSION=)(?:'([^']*)'|"([^"]*)"|(\S+))/;

/**
 * Rewrite a Bedrock setupScript: resolve VERSION to the pinned build (LATEST -> pin; explicit kept) and add
 * `-e TRANSPORT=raknet` unless the script already sets a TRANSPORT. No-op for other families/images.
 * Idempotent.
 */
export function applyBedrockSetup(setupScript: string, family: string | null): string {
  if (family !== "bedrock" || !/itzg\/minecraft-bedrock-server/.test(setupScript)) return setupScript;
  let out = setupScript;
  const m = VERSION_ENV_RE.exec(out);
  if (m) {
    const cur = m[2] ?? m[3] ?? m[4] ?? "";
    out = out.replace(VERSION_ENV_RE, `$1${shellWord(resolveBedrockVersion(cur))}`);
  } else {
    out = out.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e VERSION=${shellWord(BEDROCK_KNOWN_GOOD_VERSION)}`);
  }
  if (!/-e\s+TRANSPORT=/.test(out)) {
    out = out.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e TRANSPORT=${BEDROCK_TRANSPORT}`);
  }
  return out;
}

function shellWord(v: string): string {
  return /^[A-Za-z0-9._-]+$/.test(v) ? v : `'${v.replace(/'/g, `'\\''`)}'`;
