export const BEDROCK_LATEST = "LATEST";

/** What a stored VERSION really runs. LATEST/blank -> the pinned build; PREVIEW and explicit builds pass through. */
export function resolveBedrockVersion(v: unknown): string {
  const s = v == null ? "" : String(v).trim();
  if (!s || s.toUpperCase() === BEDROCK_LATEST) return BEDROCK_KNOWN_GOOD_VERSION;
  if (s.toUpperCase() === "PREVIEW") return "PREVIEW";
  return s;
}

/** Label for the "Latest" option / variant: says honestly what it means. */
export const BEDROCK_LATEST_LABEL = `Recommended (Nxeon-tested build ${BEDROCK_KNOWN_GOOD_VERSION})`;
export const BEDROCK_PREVIEW_LABEL =
  "Preview (Microsoft's Bedrock Preview build; untested by Nxeon and may not accept connections)";

const VERSION_ENV_RE = /(-e\s+VERSION=)(?:'([^']*)'|"([^"]*)"|(\S+))/;

/**
 * Rewrite a Bedrock setupScript: resolve VERSION to the pinned build (LATEST -> pin; explicit kept) and add
 * `-e TRANSPORT=raknet` unless the script already sets a TRANSPORT. No-op for other families/images.
 * Idempotent.
 */
export function applyBedrockSetup(setupScript: string, family: string | null): string {
  if (family !== "bedrock" || !/itzg\/minecraft-bedrock-server/.test(setupScript)) return setupScript;
  let out = setupScript;
  const m = VERSION_ENV_RE.exec(out);
  if (m) {
    const cur = m[2] ?? m[3] ?? m[4] ?? "";
    out = out.replace(VERSION_ENV_RE, `$1${shellWord(resolveBedrockVersion(cur))}`);
  } else {
    out = out.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 -e VERSION=${shellWord(BEDROCK_KNOWN_GOOD_VERSION)}`);
