export function applyGameConfigEnv(
  setupScript: string,
  family: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): string {
  if (!family || !gameConfig) return setupScript;
  const schema = schemaFor(family);
  if (!schema) return setupScript;
  let out = setupScript;
  for (const field of schema.fields) {
    const raw = gameConfig[field.key];
    if (raw === undefined || raw === null) continue;
    // envKey lets a readable schema key (e.g. "world") differ from the
    // literal docker env var name the image expects (e.g. "WORLD_NAME") —
    // see ConfigField.envKey's doc comment in lib/game-config.ts.
    const envName = field.envKey ?? field.key;
    const re = new RegExp(`-e\\s+${envName}=(?:'[^']*'|"[^"]*"|\\S*)`);
    if (!re.test(out)) continue; // this field isn't docker-env-driven in this script — leave it alone
    // A BLANK identity value never overrides a real catalog one (2026-10-02,
    // projectzomboid-syep3t): validateConfig fills every missing field with its
    // schema default, PZ's ADMIN_USERNAME default was "", and this line then
    // turned the catalog's `-e ADMIN_USERNAME=admin` into `-e ADMIN_USERNAME=''`
    // — the game exits on start with `invalid username given to
    // "-adminusername"`, forever. Blank means "no choice made" here.
    if (String(raw).trim() === "" && isIdentityEnvKey(envName)) {
      const current = scriptEnvValue(out, envName);
      if (current !== null && current.trim() !== "") continue;
    }
    const escaped = String(raw).replace(/'/g, `'\\''`);
    out = out.replace(re, `-e ${envName}='${escaped}'`);
  }
  return out;
}

/**
 * If a GAME OsTemplate's setupScript installs the game via a detached
 * `docker run -d --name <container> ...` (true for every game image today —
 * see the OsTemplate rows for minecraft/terraria/ark/etc., all `docker run -d`),
 * rewrite the invocation to `docker create` and append a generated systemd unit
 * that starts/stops the container. Also caps the container's log driver
 * (`--log-opt max-size=10m --log-opt max-file=3`) — see the comment at the
 * `createCmd` line below for why.
 *
 * WHY THIS EXISTS: the whole game control panel — GAME_POWER start/stop/restart,
 * GAME_BACKUP, log tailing (lib/game-control.ts + worker/game-control.ts) —
 * resolves the running game exclusively via `systemctl cat <serviceHint>` /
 * `journalctl -u <unit>`. A bare `docker run -d` creates no systemd unit at all,
 * so every one of those lookups comes back empty and every control action fails
 * silently, on every game family, on every order. Found 2026-08-26 diagnosing a
 * customer's Terraria server (cmt9ss7ln000xhlrx0gch9fcx) that could never be
 * started/stopped from the dashboard even though PROVISION had completed
 * successfully — the container was in fact running, just entirely invisible to
 * systemd.
 *
 * The generated unit is named after the family's FIRST serviceHint, not the
 * docker container's own `--name` — the two don't always match (minecraft's
 * image runs as container "mc" but its control-spec hints are "minecraft" /
 * "minecraft-server") — so `systemctl cat <hint>` resolves regardless of what an
 * individual image's setup script happened to call its container.
 *
 * Intentionally conservative: any setupScript that doesn't match the exact
 * `docker run -d --name X ...` shape (or any non-game family, e.g. the
 * LAMP/WordPress/Caddy panel images that already install a real native systemd
 * service) is returned completely unchanged.
 *
 * Moved here from worker/index.ts 2026-09-24 (alongside `buildGameSetupScript`
 * below) so worker/game-control.ts — which worker/index.ts itself imports, so
 * it cannot import anything back from worker/index.ts without a circular
 * dependency — can also build a real reinstall script for the Danger Zone's
 * wipe/reinstall action. Purely a relocation: behavior is unchanged.
 */
export function wrapDockerGameService(setupScript: string, family: string | null): string {
  if (!isGameFamily(family)) return setupScript;
  const unitName = controlSpec(family)?.serviceHints[0];
  if (!unitName) return setupScript;

  const re = /docker run\s+(?:-d|--detach)\b(.*?)\s+--name[= ]("?)([A-Za-z0-9_.-]+)\2(.*)$/.exec(setupScript.trim());
  if (!re) return setupScript;
  const [full, before, , containerName, after] = re;
  const matchIndex = setupScript.indexOf(full);

 * never drift from the unit that actually got installed.
 */
async function resolveGameUnit(conn: Client, family: string): Promise<string | null> {
  const hints = controlSpec(family)?.serviceHints ?? [];
  if (!hints.length) return null;
  const probe = hints
    .map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`)
    .join(" ");
  const { stdout } = await execRemote(conn, probe);
  const hit = stdout
    .split(/\r?\n/)
    .map((s) => s.trim())
    .find((s) => s.endsWith(".service"));
  return hit ?? null;
}

/** Dispatch to the correct family renderer. Exported for direct, real-server
 *  verification of a family's real-apply path (see REAL_APPLY_FAMILIES's own
 *  comment for what "confirmed" means) — not called externally otherwise. */
export async function applyRealConfig(
  server: SshServer,
  family: string,
  values: Values,
  opts?: { changed?: string[]; restart?: boolean },
): Promise<ApplyOutcome> {
  return withSsh(server, async (conn, sftp) => {
    switch (family) {
      case "minecraft":
        return applyMinecraft(conn, sftp, values, server);
      case "rust":
        return applyRust(conn, sftp, values, server.gameVariant ?? "vanilla");
      case "valheim":
        return applyValheim(conn, sftp, values, server.gameVariant ?? "vanilla");
      case "palworld":
        return applyPalworld(conn, sftp, values);
      case "bedrock":
        return applyBedrock(conn, sftp, values);
      // dayz: now an applier (worker/game-config-appliers/dayz.ts); the old inline applyDayZ is gone.
      case "fivem":
        // Feature-flagged family (lib/fivem.ts). File-based cfg renderer —
        // NOT in REAL_APPLY_FAMILIES until live-verified, same rule as dayz.
        return applyFivem(conn, server.id, values);
      default: {
        // Applier registry (worker/game-config-appliers/index.ts): one file per family.
        const applier = getApplier(family);
        if (!applier) return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
        return runApplier(applier, {
          server: { id: server.id },
          values,
          changed: opts?.changed,
          restartRequested: opts?.restart === true,
          variant: server.gameVariant ?? null,
          guest: {
            exec: (cmd, timeoutMs) => execRemote(conn, cmd, timeoutMs),
            readFile: (path) => sftpRead(sftp, path),
            writeFile: (path, content) => sftpWrite(sftp, path, content),
          },
          unit: await resolveGameUnit(conn, family),
          waitPort: () =>
            waitForGamePort(server as unknown as ControlServer, Math.max(60_000, controlSpec(family) ? startWindowMs(controlSpec(family)!) : 0), 5_000),
        });
      }
    }
  });
}

