/** Honest one-paragraph copy for the auto-update toggle, per plan. */
export function autoUpdateCopy(plan: AutoUpdatePlan, gameName: string, variantLabel?: string | null): string {
  switch (plan.kind) {
    case "bump":
    case "current":
      return (
        `When on, every 6 hours we check for a newer ${gameName} version that Nxeon supports. If there is one, ` +
        `we back up your world first, switch your server to it, restart, check that it really came back online, ` +
        `and tell you exactly what changed. If it doesn't come back, we put the previous version back.`
      );
    case "follows-latest":
      return (
        `Your server is set to “Always latest”, so ${gameName} already updates itself every time it restarts — ` +
        `this switch can't change that. Pick a fixed version in Game settings if you'd rather choose when to update.`
      );
    case "channel":
        return (
          `When on, every 6 hours we check the official ${gameName} server build channel you picked in Settings ` +
          `(Recommended or Latest). If a newer build is out, we download and verify it while your server keeps running, ` +
          `then restart onto it and check it came back. Nothing restarts when you're already on the newest build. ` +
          `Pin a build in Settings to stop automatic updates.`
        );
    case "none":
      if (plan.reason === "pinned-for-mods") {
        return (
          `${variantLabel ?? "Modded"} servers stay on the ${gameName} version your plugins or mods are built for, ` +
          `so we never change it automatically. With this on we only check every 6 hours that your server is ` +
          `running — nothing is downloaded and nothing restarts. Change the version yourself in Game settings.`
        );
      }
      return (
        `${gameName} has no automatic update source on Nxeon yet. With this on we only check every 6 hours that ` +
        `your server is running — nothing is downloaded and nothing restarts. To update, upload new server files ` +
        `in the Files tab, or reinstall the game.`
      );
  }

