cd /tank/nxeon-wt-bedrockfix; cat > scripts/bedrock-protect.ts <<'EOF'
/**
 * Protect existing Minecraft Bedrock servers against the BDS 1.26.50+ NetherNet default
 * (docs/DOCUMENTATION.md, "Bedrock never opens its game port").
 *
 *   npx tsx scripts/bedrock-protect.ts                 DRY RUN over every Bedrock server (read-only: one `docker inspect` each)
 *   npx tsx scripts/bedrock-protect.ts --apply <hostname> [<hostname>...]
 *
 * --apply RECREATES that server's `bedrock` container (brief restart, automatic rollback on failure) with
 * VERSION resolved from LATEST to the platform pin and TRANSPORT=raknet; no customer setting or world data
 * changes. Containers cannot change env in place, so there is no restart-free variant. Only run --apply with
 * the owner's approval, and never on a server with players online without telling the customer.
 */
import { db } from "../lib/db";
import { protectBedrockServer } from "../worker/game-config";
import { BEDROCK_KNOWN_GOOD_VERSION } from "../lib/bedrock-version";

async function main() {
  const args = process.argv.slice(2);
  const apply = args.includes("--apply");
  const names = args.filter((a) => !a.startsWith("--"));
  if (apply && names.length === 0) {
    console.error("--apply needs explicit hostnames (never applied fleet-wide by default)");
    process.exit(2);
  }
  const servers = await db.server.findMany({
    where: { osTemplate: { family: "bedrock" }, status: "RUNNING", ...(apply ? { hostname: { in: names } } : {}) },
    include: { node: true, dedicatedIp: true },
  });
  console.log(`${apply ? "APPLY" : "DRY RUN"} (pin ${BEDROCK_KNOWN_GOOD_VERSION}) over ${servers.length} server(s)`);
  for (const s of servers) {
    try {
      const r = await protectBedrockServer(s as any, { dryRun: !apply });
      console.log(`${s.hostname}: ${r.ok ? "ok" : "FAILED"} - ${r.changes.join("; ") || "no change"} (${r.note})`);
    } catch (e: any) {
      console.log(`${s.hostname}: ERROR ${String(e?.message ?? e).slice(0, 200)}`);
    }
  }
  process.exit(0);
}
main();
EOF
cat > test/bedrock-version.test.ts <<'EOF'
import { describe, it, expect } from "vitest";
import {
  BEDROCK_KNOWN_GOOD_VERSION,
  resolveBedrockVersion,
  applyBedrockSetup,
  bedrockEnvProtection,
  bedrockStartupHint,
} from "../lib/bedrock-version";
import { applyGameConfigEnv, buildGameSetupScript } from "../worker/game-variant";
import { schemaFor } from "../lib/game-config";

const SCRIPT =
  `curl -fsSL https://get.docker.com | sh && docker run -d --name bedrock -e EULA=TRUE -e SERVER_NAME="Nxeon Bedrock Server" -e GAMEMODE=survival -e DIFFICULTY=normal -e LEVEL_NAME=Bedrock -e MAX_PLAYERS=10 -e ALLOW_CHEATS=false -e VERSION=LATEST -p 19132:19132/udp -v /opt/bedrock:/data --restart unless-stopped itzg/minecraft-bedrock-server`;

describe("resolveBedrockVersion", () => {
  it("maps LATEST/blank to the pin, keeps PREVIEW and explicit builds", () => {
    expect(resolveBedrockVersion("LATEST")).toBe(BEDROCK_KNOWN_GOOD_VERSION);
    expect(resolveBedrockVersion("latest")).toBe(BEDROCK_KNOWN_GOOD_VERSION);
    expect(resolveBedrockVersion("")).toBe(BEDROCK_KNOWN_GOOD_VERSION);
    expect(resolveBedrockVersion(undefined)).toBe(BEDROCK_KNOWN_GOOD_VERSION);
    expect(resolveBedrockVersion("PREVIEW")).toBe("PREVIEW");
    expect(resolveBedrockVersion("1.26.45.1")).toBe("1.26.45.1");
  });
});

describe("applyBedrockSetup", () => {
  it("pins LATEST and adds TRANSPORT=raknet", () => {
    const out = applyBedrockSetup(SCRIPT, "bedrock");
    expect(out).toContain(`-e VERSION=${BEDROCK_KNOWN_GOOD_VERSION} `);
    expect(out).not.toContain("VERSION=LATEST");
    expect(out).toContain("-e TRANSPORT=raknet");
  });
  it("is idempotent and keeps explicit/quoted versions", () => {
    const once = applyBedrockSetup(SCRIPT.replace("VERSION=LATEST", "VERSION='1.26.45.1'"), "bedrock");
    expect(once).toContain("-e VERSION=1.26.45.1 ");
    expect(applyBedrockSetup(once, "bedrock")).toBe(once);
  });
  it("adds a VERSION when the script has none", () => {
    const out = applyBedrockSetup(SCRIPT.replace(" -e VERSION=LATEST", ""), "bedrock");
    expect(out).toContain(`-e VERSION=${BEDROCK_KNOWN_GOOD_VERSION}`);
  });
  it("never overrides a script's own TRANSPORT and ignores other families", () => {
    expect(applyBedrockSetup(SCRIPT + " -e TRANSPORT=nethernet", "bedrock").match(/TRANSPORT=/g)).toHaveLength(1);
    expect(applyBedrockSetup(SCRIPT, "minecraft")).toBe(SCRIPT);
    expect(applyBedrockSetup("docker run -d --name mc -e VERSION=LATEST x", "bedrock")).toBe("docker run -d --name mc -e VERSION=LATEST x");
  });
  it("works after the customer's quoted LATEST is substituted by applyGameConfigEnv", () => {
    const withCfg = applyGameConfigEnv(SCRIPT, "bedrock", { VERSION: "LATEST" });
    expect(withCfg).toContain("VERSION='LATEST'");
    expect(applyBedrockSetup(withCfg, "bedrock")).toContain(`-e VERSION=${BEDROCK_KNOWN_GOOD_VERSION} `);
    const preview = applyBedrockSetup(applyGameConfigEnv(SCRIPT, "bedrock", { VERSION: "PREVIEW" }), "bedrock");
    expect(preview).toContain("-e VERSION=PREVIEW ");
  });
  it("is wired into buildGameSetupScript", () => {
    const out = buildGameSetupScript({ osTemplate: { setupScript: SCRIPT, family: "bedrock" }, gameConfig: { VERSION: "LATEST" } });
    expect(out).toContain("TRANSPORT=raknet");
    expect(out).toContain(`VERSION=${BEDROCK_KNOWN_GOOD_VERSION}`);
    expect(out).not.toMatch(/VERSION='?LATEST/);
  });
});

describe("bedrockEnvProtection", () => {
  it("reports what an existing LATEST container would change", () => {
    const p = bedrockEnvProtection(new Map([["VERSION", "LATEST"]]));
    expect(p.set).toEqual({ VERSION: BEDROCK_KNOWN_GOOD_VERSION, TRANSPORT: "raknet" });
    expect(p.changes).toHaveLength(2);
  });
  it("is empty for an already protected container", () => {
    expect(bedrockEnvProtection(new Map([["VERSION", "1.26.45.1"], ["TRANSPORT", "raknet"]])).changes).toEqual([]);
  });
});

describe("bedrockStartupHint", () => {
  it("recognises the NetherNet-default signature", () => {
    expect(bedrockStartupHint("[INFO] Accepting clients on [::]:19132\n[INFO] Server started.")).toMatch(/NetherNet/);
  });
  it("does not blame a healthy RakNet start", () => {
    expect(bedrockStartupHint("IPv4 supported, port: 19132\nAccepting clients on [::]:19132")).toBeNull();
    expect(bedrockStartupHint("")).toBeNull();
  });
});

describe("bedrock schema labels", () => {
  it("says what Latest really means", () => {
    const f = schemaFor("bedrock")!.fields.find((x) => x.key === "VERSION")! as any;
    const latest = f.options.find((o: any) => o.value === "LATEST");
    expect(latest.label).toContain(BEDROCK_KNOWN_GOOD_VERSION);
    expect(latest.label).not.toMatch(/auto-update/i);
  });
});
EOF
