  });
  it("works after the customer's quoted LATEST is substituted by applyGameConfigEnv", () => {
    const withCfg = applyGameConfigEnv(SCRIPT, "bedrock", { VERSION: "LATEST" });
    expect(withCfg).toContain("VERSION='LATEST'");
    expect(applyBedrockSetup(withCfg, "bedrock")).toContain(`-e VERSION=${BEDROCK_KNOWN_GOOD_VERSION} `);
    const preview = applyBedrockSetup(applyGameConfigEnv(SCRIPT, "bedrock", { VERSION: "PREVIEW" }), "bedrock");
    expect(preview).toContain("-e VERSION=PREVIEW ");
  });
  it("is wired into buildGameSetupScript", () => {
    const out = buildGameSetupScript({ osTemplate: { setupScript: SCRIPT, family: "bedrock" }, gameConfig: { VERSION: "LATEST" } });
    expect(out).toContain("TRANSPORT=raknet");
    expect(out).toContain(`VERSION=${BEDROCK_KNOWN_GOOD_VERSION}`);
    expect(out).not.toMatch(/VERSION='?LATEST/);
  });
});

describe("bedrockEnvProtection", () => {
  it("reports what an existing LATEST container would change", () => {
    const p = bedrockEnvProtection(new Map([["VERSION", "LATEST"]]));
    expect(p.set).toEqual({ VERSION: BEDROCK_KNOWN_GOOD_VERSION, TRANSPORT: "raknet" });
    expect(p.changes).toHaveLength(2);
  });
  it("is empty for an already protected container", () => {
    expect(bedrockEnvProtection(new Map([["VERSION", "1.26.45.1"], ["TRANSPORT", "raknet"]])).changes).toEqual([]);
  });
});

describe("bedrockStartupHint", () => {
  it("recognises the NetherNet-default signature", () => {
    expect(bedrockStartupHint("[INFO] Accepting clients on [::]:19132\n[INFO] Server started.")).toMatch(/NetherNet/);
  });
  it("does not blame a healthy RakNet start", () => {
    expect(bedrockStartupHint("IPv4 supported, port: 19132\nAccepting clients on [::]:19132")).toBeNull();
    expect(bedrockStartupHint("")).toBeNull();
  });
});

describe("bedrock schema labels", () => {
  it("says what Latest really means", () => {
    const f = schemaFor("bedrock")!.fields.find((x) => x.key === "VERSION")! as any;
    const latest = f.options.find((o: any) => o.value === "LATEST");
    expect(latest.label).toContain(BEDROCK_KNOWN_GOOD_VERSION);
    expect(latest.label).not.toMatch(/auto-update/i);
  });
});
